import time
import secrets

class TokenEngine:
    def __init__(self):
        self.refresh_store = {}  # token -> {user_id, family_id, used}

    def issue_token_pair(self, user_id, family_id=None):
        if not family_id:
            family_id = secrets.token_hex(8)
        access_token = f"acc_{user_id}_{int(time.time()) + 900}"
        refresh_token = secrets.token_hex(16)
        self.refresh_store[refresh_token] = {
            "user_id": user_id,
            "family_id": family_id,
            "used": False
        }
        return access_token, refresh_token

    def rotate_refresh_token(self, old_refresh_token):
        record = self.refresh_store.get(old_refresh_token)
        if not record:
            return None, "Invalid token"
        if record["used"]:
            # Replay attack detected! Invalidate entire family
            fam = record["family_id"]
            for t, data in list(self.refresh_store.items()):
                if data["family_id"] == fam:
                    del self.refresh_store[t]
            return None, "BREACH: Replay detected. Family revoked!"

        record["used"] = True
        return self.issue_token_pair(record["user_id"], record["family_id"])

